  ('fully_burdened_labor_cost','labor_economics','Business Builder','Fully burdened labor cost','Fully burdened labor cost','paid_hours * (hourly_wage + benefits_per_hour + payroll_taxes_per_hour + overhead_per_hour)','["paid_hours","hourly_wage","benefits_per_hour","payroll_taxes_per_hour","overhead_per_hour"]','[]','money','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
  ('trade_bid_price','construction_trades','Business Builder','Trade job bid estimate','Trade job bid estimate','((productive_hours / utilization_rate) * burdened_cost_per_paid_hour + materials_cost + other_direct_cost) * (1 + markup_rate)','["productive_hours","utilization_rate","burdened_cost_per_paid_hour","materials_cost","other_direct_cost","markup_rate"]','[]','money','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
  ('economic_profit','labor_economics','Business Builder','Economic profit after opportunity cost','Economic profit after opportunity cost','chosen_net_benefit - best_foregone_net_benefit','["chosen_net_benefit","best_foregone_net_benefit"]','[]','money','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
  ('project_net_present_value','building_economics','Business Builder','Project net present value','Project net present value','annual_net_cash_flow * (1 - (1 + discount_rate)^(-years)) / discount_rate - upfront_cost','["upfront_cost","annual_net_cash_flow","discount_rate","years"]','[]','money','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
