  ('concrete_volume_m3','construction_trades','Business Builder','Concrete geometric volume','Concrete geometric volume','length_meters * width_meters * depth_meters','["length_meters","width_meters","depth_meters"]','[]','cubic_meters','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
