  ('paint_gallons','construction_trades','Business Builder','Paint quantity in US gallons','Paint quantity in US gallons','surface_square_feet * coats * (1 + waste_rate) / coverage_square_feet_per_gallon','["surface_square_feet","coats","waste_rate","coverage_square_feet_per_gallon"]','[]','US_gallons','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
