  ('pipe_flow_m3_s','trade_plumbing','Business Builder','Estimated circular pipe flow','Estimated circular pipe flow','pi * (inside_diameter_meters / 2)^2 * fluid_speed_meters_per_second','["inside_diameter_meters","fluid_speed_meters_per_second"]','[]','cubic_meters_per_second','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
