  ('byte_transfer_seconds','computing_engineering','Creator Studio','Theoretical transfer duration','Theoretical transfer duration','payload_bytes * 8 / effective_bits_per_second','["payload_bytes","effective_bits_per_second"]','[]','seconds','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
  ('compute_job_cost','computing_engineering','Creator Studio','Compute and storage job cost','Compute and storage job cost','runtime_seconds * compute_rate_per_hour / 3600 + storage_gib * storage_rate_per_gib_month * months_stored','["runtime_seconds","compute_rate_per_hour","storage_gib","storage_rate_per_gib_month","months_stored"]','[]','money','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
