  ('telescope_rayleigh_arcseconds','space_science','Creator Studio','Diffraction-limited telescope resolution','Diffraction-limited telescope resolution','1.22 * wavelength_nanometers * 1e-9 / aperture_meters * 206264.806247','["wavelength_nanometers","aperture_meters"]','[]','arcseconds','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
  ('quantum_ideal_one_probability','quantum_research','Creator Studio','Ideal qubit one-state probability','Ideal qubit one-state probability','sin(rotation_radians / 2)^2','["rotation_radians"]','[]','probability','["owner","admin"]','active','Deterministic estimator; sources and limitations: docs/research/engineering-calculators-2026-10-09.md.'),
