  ('project_variable_cash_flow_npv','building_economics','Business Builder','Variable cash-flow project NPV','Variable cash-flow project NPV','sum(cash_flows[t]/(1+discount_rate)^(t+1)) - upfront_cost','["cash_flows","discount_rate","upfront_cost"]','[]','money','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('roof_pitch_surface_sqft','construction_trades','Business Builder','Sloped roofing surface estimate','Sloped roofing surface estimate','plan_area_square_feet * sqrt(1 + (rise_per_12/12)^2)','["plan_area_square_feet","rise_per_12"]','[]','square_feet','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('trade_bid_gross_margin_percent','construction_trades','Business Builder','Bid gross margin after direct job costs','Bid gross margin after direct job costs','100 * (bid_price - direct_job_cost) / bid_price','["bid_price","direct_job_cost"]','[]','percent','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('base64_encoded_bytes','computing_engineering','Creator Studio','Base64 output byte length','Base64 output byte length','4 * ceil(source_bytes / 3)','["source_bytes"]','[]','bytes','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('circular_orbit_speed_m_s','space_science','Business Builder','Ideal circular orbital speed','Ideal circular orbital speed','sqrt(gravitational_parameter_m3_s2 / orbital_radius_meters)','["gravitational_parameter_m3_s2","orbital_radius_meters"]','[]','meters_per_second','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('nadir_ground_sample_distance_m','space_science','Creator Studio','Ideal optical nadir GSD','Ideal optical nadir GSD','sensor_pixel_pitch_micrometers * 1e-6 * altitude_meters / focal_length_meters','["sensor_pixel_pitch_micrometers","altitude_meters","focal_length_meters"]','[]','meters_per_pixel','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('combined_standard_uncertainty','measurement_science','Business Builder','Independent standard uncertainties combined','Independent standard uncertainties combined','sqrt(uncertainty_a^2 + uncertainty_b^2)','["uncertainty_a","uncertainty_b"]','[]','input_unit','["owner","admin"]','active','Bounded deterministic engineering estimator; see research/engineering-calculators-2026-10-09.md'),
  ('correlated_standard_uncertainty','measurement_science','Business Builder','Two correlated standard uncertainties','Two correlated standard uncertainties','sqrt(uncertainty_a^2 + uncertainty_b^2 + 2 * correlation_coefficient * uncertainty_a * uncertainty_b)','["uncertainty_a","uncertainty_b","correlation_coefficient"]','[]','input_unit','["owner","admin"]','active','Covariance-aware standard uncertainty: input uncertainties share a unit, rho is bounded from -1 to 1; use NIST TN 1297.')
